select id, customer_id, start_date, monthly_fee, status, sum(monthly_fee) over (partition by status, plan order by monthly_fee, id rows between unbounded preceding and current row) as running_monthly_fee, round(monthly_fee / sum(monthly_fee) over (partition by customer_id), 4) as monthly_fee_share, round(monthly_fee / sum(monthly_fee) over (partition by plan), 4) as monthly_fee_share_2, last_value(monthly_fee) ignore nulls over (partition by plan order by start_date, id rows between unbounded preceding and current row) as last_known_monthly_fee, ntile(4) over (order by monthly_fee desc, id) as monthly_fee_bucket from subscriptions;
